// The JSON files are generated by `pnpm run i18n:gen` from /locales (git-ignored); `dev`, `build`,
// `check` and `test` run it first.
import de from "./generated/de.json";
import en from "./generated/en.json";
import es from "./generated/es.json";
import fr from "./generated/fr.json";

/** Shipped locales; the language codes match `SettingsState.language` in the contract. */
export const LOCALES = ["en", "de", "fr", "es"] as const;
export type Locale = (typeof LOCALES)[number];

export const DEFAULT_LOCALE: Locale = "en";

/** A nested catalogue as generated: groups of groups of messages. */
export interface Bundle {
  readonly [key: string]: string | Bundle;
}

export const BUNDLES: Readonly<Record<Locale, Bundle>> = { en, de, fr, es };

export function isLocale(value: unknown): value is Locale {
  return typeof value === "string" && (LOCALES as readonly string[]).includes(value);
}

/**
 * The locale to show: an explicit choice wins, otherwise the first browser language we ship
 * (`de-AT` matches `de`), otherwise English.
 */
export function resolveLocale(
  explicit: string | null,
  browserLanguages: readonly string[],
): Locale {
  if (isLocale(explicit)) return explicit;
  for (const tag of browserLanguages) {
    const base = tag.toLowerCase().split("-")[0];
    if (isLocale(base)) return base;
  }
  return DEFAULT_LOCALE;
}
